(function () {
  "use strict";

  document.documentElement.classList.add("js");

  // Reveal sections on scroll
  var items = document.querySelectorAll(".reveal");

  if (!("IntersectionObserver" in window)) {
    items.forEach(function (el) {
      el.classList.add("is-visible");
    });
  } else {
    var observer = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-visible");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.08 }
    );

    items.forEach(function (el) {
      observer.observe(el);
    });
  }

  // Force file download for the PDF button (instead of opening in the browser PDF viewer)
  var pdfB64 = "";

  function triggerBlobDownload(blob, filename) {
    var blobUrl = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.style.display = "none";
    a.href = blobUrl;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(function () {
      document.body.removeChild(a);
      URL.revokeObjectURL(blobUrl);
    }, 1000);
  }

  function downloadFromBase64(filename) {
    var bin = atob(pdfB64);
    var len = bin.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) {
      bytes[i] = bin.charCodeAt(i);
    }
    var blob = new Blob([bytes], { type: "application/octet-stream" });
    triggerBlobDownload(blob, filename);
  }

  var pdfBtn = document.querySelector(".btn--pdf");
  if (pdfBtn) {
    pdfBtn.addEventListener("click", function (e) {
      e.preventDefault();
      var url = pdfBtn.getAttribute("href") || "artemis-gharakhanian.pdf";
      var filename = pdfBtn.getAttribute("download") || "artemis-gharakhanian.pdf";

      if (window.location.protocol === "file:") {
        downloadFromBase64(filename);
        return;
      }

      fetch(url)
        .then(function (res) {
          if (!res.ok) throw new Error("Network error");
          return res.arrayBuffer();
        })
        .then(function (buf) {
          var blob = new Blob([buf], { type: "application/octet-stream" });
          triggerBlobDownload(blob, filename);
        })
        .catch(function () {
          downloadFromBase64(filename);
        });
    });
  }
})();
